add_filter( 'woocommerce_cart_item_subtotal', 'perfectpixel_item_subtotal_after_coupon', 99, 3 );

function perfectpixel_item_subtotal_after_coupon( $subtotal, $cart_item, $cart_item_key ) {
	$before = (float) $cart_item['line_subtotal'];
	$after  = (float) $cart_item['line_total'];
	if ( WC()->cart->display_prices_including_tax() ) {
		$before += (float) $cart_item['line_subtotal_tax'];
		$after  += (float) $cart_item['line_tax'];
	}
	if ( $after < $before ) {
		return '<del>' . wc_price( $before ) . '</del> <ins>' . wc_price( $after ) . '</ins>';
	}
	return $subtotal;
}
